import fs from 'node:fs/promises';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {fileURLToPath,pathToFileURL} from 'node:url';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const verification=path.resolve(root,'../..');
const model=path.join(verification,'prototype/shared/model.ts');
const hash=b=>createHash('sha256').update(b).digest('hex');
const before=hash(await fs.readFile(model));
const {build}=await import(pathToFileURL(path.join(verification,'repos/editor-online/node_modules/vite/dist/node/index.js')));
const entry=path.join(root,'shared/entry.ts');
await fs.writeFile(entry,`import {createComplexInventoryApp} from './index.ts';\nconst g=globalThis as any;\nif(!g.complexInventoryApp) g.complexInventoryApp=createComplexInventoryApp();\n`);
const result=await build({configFile:false,root,publicDir:false,logLevel:'silent',build:{write:false,minify:false,target:'es2020',sourcemap:true,lib:{entry,formats:['iife'],name:'ComplexInventory'}}});
const output=(Array.isArray(result)?result:[result]).flatMap(r=>r.output);
const chunk=output.find(c=>c.type==='chunk');
if(!chunk||!chunk.map)throw Error('No bundle or source map');
if(!Object.keys(chunk.modules).some(p=>path.resolve(p)===model))throw Error('Original shared reward model is absent from bundle');
if(before!==hash(await fs.readFile(model)))throw Error('Original model changed');
await fs.mkdir(path.join(root,'dist'),{recursive:true});
const code=chunk.code.replace(/\n?\/\/# sourceMappingURL=.*$/m,'')+'\n';
await fs.writeFile(path.join(root,'dist/ComplexInventoryApp.txt'),code);
await fs.writeFile(path.join(root,'dist/ComplexInventoryApp.txt.map'),chunk.map.toString());
await fs.writeFile(path.join(root,'dist/build.json'),JSON.stringify({timestamp:new Date().toISOString(),format:'IIFE ES2020',entry,bundleSha256:hash(code),bytes:Buffer.byteLength(code),modelSha256:before,modelUnchanged:true,inputs:Object.keys(chunk.modules)},null,2));
console.log(JSON.stringify({bytes:Buffer.byteLength(code),sha256:hash(code),modelSha256:before}));
